#!/usr/bin/env python3
"""Seedance image-to-video specs for take two: media/gen/specs/t2_<id>_t<k>.json (git-ignored).
   python3 fable/take2/gen/gen_clips.py ID[=still] [...] [--take=1]   then  $PY tools/gen/gen.py submit media/gen/specs/t2_<id>_t1.json ...
First frames are work_fable/take2/stills/<still>.jpg|png re-encoded to work_fable/take2/refs/<id>.jpg (2048x1152)."""
import json, os, sys, subprocess
ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), "..", "..", ".."))
KEEP = ("Animate the first frame exactly as drawn: same framing, same composition, same character, and the same hand-made medium in every frame. It is {m} and must stay {m} throughout, never photographic and never 3D. ")
# Lettering. Take 1 said "the lettering (RARE EARTH and 1420 MHz) stays as drawn" for every view; in front and side views the model then
# wrote RARE EARTH on the chest and moved the patch about. From take 2 the sentence depends on what the shot can see.
LETTER = {"back": "The lettering on her jacket (RARE EARTH on the back and 1420 MHz on the sleeve patch) stays exactly as drawn in the first frame.",
          "front": "There is no lettering anywhere on the front of her jacket: no label, no tag, no words on the chest. The only lettering is 1420 MHz on the one round patch on her left upper arm, which stays exactly where it is in the first frame; her other arm has no patch.",
          "side": "Her torso never twists: she stays exactly side-on, so the back of her jacket is never seen. No lettering appears anywhere except 1420 MHz on the one round patch on her left upper arm, which stays exactly where it is in the first frame; her other arm has no patch; no words on the jacket."}
LETTER["none"] = "There is no lettering anywhere in the picture."
LETTER["backc"] = LETTER["back"]
VIEWS = {"main_face": "front", "main_split": "front", "cross_wushu": "backc", "cross_ames": "back", "cross_hackerhouses": "back", "cross_violet": "back", "main_light": "front",
         "main_release": "back", "hero_feet": "none", "fold_reach": "front", "fold_chest": "front", "look_back": "back", "main_back_wide": "backc", "runner_main": "side",
         "patch_resolve": "front", "runner_pencil": "side", "runner_pixel": "side", "cross_wetlab": "back", "hero_paper": "front"}
END0 = " Her mouth stays closed; she does not speak or sing. {L} One continuous shot, no cut. No captions, no subtitles, no added text."
END = "{END}"
RUN = ("She runs in place at a steady sprint, exactly side-on, as if on a treadmill: an even, regular stride, left and right legs strictly alternating, arms pumping, her hair and trouser straps streaming behind her. "
       "She stays in the same place in the frame and at the same size the whole time: her whole body, from the top of her head to the soles of her trainers, stays inside the frame with space around it, exactly as in the first frame; the camera is locked off and never zooms in. The background stays a completely plain, flat, even, empty grey with nothing in it: no ground, no shadow, no scenery, no lines.")
C = {  # id: (still, medium, action, extra input)
 "patch_resolve": ("patchwork_a1", "a hand-made illustration", None, {"last": "resolve_a1"}),
 "runner_pencil": ("runner_pencil_a1", "a coloured-pencil drawing", RUN, {}),
 "runner_pixel": ("runner_pixel_a1", "16-bit pixel art with crisp square pixels, moving in small pixel-art animation steps", RUN, {}),
 "cross_wetlab": ("cross_wetlab_a1", "a flat cel-shaded anime drawing on black paper",
                  "She runs along the mint-green line toward the tall doorway of ivory light, with an even stride, her back to the viewer the whole time, and reaches it in about three seconds; she runs through the doorway and is gone into the ivory light. The hand-drawn strokes of light around the doorway flicker as in hand-drawn animation; inside the doorway the fine ink neurons grow slowly. The camera is locked off: no zoom, no pan.", {}),
 "hero_paper": ("hero_paper_a2", "a flat cel-shaded anime drawing on black paper, with flat colours and no glow",
                "She sprints straight toward the viewer with long, even, powerful strides, left and right legs strictly alternating in a regular rhythm, hair and trouser straps flying behind her. The camera tracks backward at exactly her speed so she stays the same size and in the same place in the frame, her whole body in frame. The thin hand-drawn coloured lines on the black paper stream past and waver slightly as in hand-drawn animation; the black paper stays black and empty. Her expression is open and determined, lips closed.", {}),
}

C.update({
 "main_face": ("main_face_a1", "a flat cel-shaded anime drawing on black paper, with flat colours and no glow", "For the first second she looks a little past the viewer, calm, and blinks once; then her eyes turn to look straight at the viewer and her chin lifts slightly, resolved. Her hair stirs in a light wind. The drawn stars twinkle a little as in hand-drawn animation and the orange line stays where it is. A very slow push-in.", {}),
 "main_split": ("main_split1_e1", "a flat cel-shaded anime drawing on black paper, with flat colours and no glow", None, {"last": "main_split4_a1"}),
 "cross_wushu": ("cross_wushu_b1", "a flat cel-shaded anime drawing on black paper, with flat colours and no glow", "She runs along the coral-red line straight to the doorway of light, with an even stride, her back to the viewer the whole time, and reaches it in about three seconds; she runs through the doorway and is gone into its light. The hand-drawn strokes of light around the doorway flicker as in hand-drawn animation; inside the doorway the woodblock print stays a still print. The camera is locked off: no zoom, no pan.", {}),
 "cross_ames": ("cross_ames_a1", "a flat cel-shaded anime drawing on black paper, with flat colours and no glow", "She runs along the bright-blue line straight to the doorway of light, with an even stride, her back to the viewer the whole time, and reaches it in about three seconds; she runs through the doorway and is gone into its light. The hand-drawn strokes of light around the doorway flicker as in hand-drawn animation; inside the doorway the pale shafts of light in the painted wind tunnel drift slowly. The camera is locked off: no zoom, no pan.", {}),
 "cross_hackerhouses": ("cross_hackerhouses_a1", "a flat cel-shaded anime drawing on black paper, with flat colours and no glow", "She runs along the mint-green line straight to the doorway of light, with an even stride, her back to the viewer the whole time, and reaches it in about three seconds; she runs through the doorway and is gone into its light. The hand-drawn strokes of light around the doorway flicker as in hand-drawn animation; inside the doorway the small blank screens of the pixel-art room flicker in pixel steps and stay blank. The camera is locked off: no zoom, no pan.", {}),
 "cross_violet": ("cross_violet_a1", "a flat cel-shaded anime drawing on black paper, with flat colours and no glow", "She runs on along the violet line with a light, even stride, her back to the viewer the whole time, away into the dark toward the upper left, growing steadily smaller; there is no doorway and she does not stop. The fine white engraved lines of the night sky shimmer as in hand-drawn animation and the engraved rings slowly widen like ripples. The camera is locked off: no zoom, no pan.", {}),
 "main_light": ("main_light_a1", "a flat cel-shaded anime drawing on black paper, with flat colours and no glow", "The small light in her cupped hands kindles: over three seconds it grows from a tiny point to a bright small star, its drawn golden rays lengthening and flickering as in hand-drawn animation, the flat warm light spreading over her fingers and cuffs. Her hands stay cupped together and almost still, the fingers curling a little round the light; each hand keeps exactly five fingers. Her face never enters the picture. A very slow push-in.", {}),
 "main_release": ("main_release_a1", "a flat cel-shaded anime drawing on black paper, with flat colours and no glow", "She lets the light go: it shoots away from her open hands along the rose-pink line toward the far left of the picture, leaving a short drawn trail, and shrinks to a point at the far end of the line within two seconds, where it stays as a tiny steady star. Her hair and jacket lift in its draught and settle; she slowly lowers her arms and watches it go, her back to the viewer the whole time. The camera is locked off.", {}),
 "hero_feet": ("hero_feet_a1", "a flat cel-shaded anime drawing on black paper, with flat colours and no glow", "Her feet run toward the left at a steady sprint with an even, regular stride, left and right feet strictly alternating, and the camera tracks alongside at exactly her speed, so the feet stay in the same place in the frame and at the same size and the level orange line stays where it is. Each time a trainer strikes the orange line, a small burst of short hand-drawn orange strokes flies up and fades. Only her feet and lower legs are ever in the picture. The black paper stays black and empty.", {}),
 "fold_reach": ("fold_reach_b1", "a flat cel-shaded anime drawing on black paper, with flat colours and no glow", "She holds her open hand out toward the viewer for one second, reaching a little further; then she slowly draws the hand back to her chest, the fingers closing gently, her eyes on the viewer the whole time, calm and warm. Her hand keeps exactly five fingers. The thin coloured lines behind her waver slightly as in hand-drawn animation. The camera is locked off.", {}),
 "fold_chest": ("fold_chest_a1", "a flat cel-shaded anime drawing on black paper, with flat colours and no glow", "She stands still with both hands crossed on her chest and her eyes closed, breathing slowly; her hair and the straps of her trousers stir gently. At about three seconds she opens her eyes and lifts her head a little, calm and glad. She stays in the same place and at the same size; the black paper on each side of her stays empty. The camera is locked off: no zoom, no pan.", {}),
 "look_back": ("look_back_a1", "a flat cel-shaded anime drawing on black paper, with flat colours and no glow", "She has just stopped and turned her head: for the first second her long hair is still swinging from the turn and settles. She holds the look back over her shoulder at the viewer, a quiet look of recognition; she blinks once and the smallest smile begins, lips closed. Her body stays facing away. The thin coloured lines in the distance glimmer slightly as in hand-drawn animation. A very slow push-in.", {}),
 "main_back_wide": ("main_back_wide_a1", "a flat cel-shaded anime drawing on black paper, with flat colours and no glow", "She stands still with her back to the viewer, her hair and trouser straps stirring in a light wind. The many thin coloured lines across the plain glimmer and waver slightly as in hand-drawn animation, the tiny lit windows flicker softly, the stars twinkle. The camera pulls back and rises very slowly and steadily, so that she becomes a little smaller and more of the plain comes into view.", {}),
 "runner_main": ("runner_main_p", "a flat cel-shaded anime drawing with a clean inked line and flat colours", RUN, {}),
})

KIT = {"piano": ("runner_piano_c1", "an opaque gouache painting with visible brush texture"), "wushu": ("runner_wushu_c1", "a woodblock print with bold carved key lines"),
       "wetlab": ("runner_wetlab_c1", "a fine pen-and-ink drawing with stippling"), "phd": ("runner_phd_c1", "a pen-plotter drawing of single-weight hatched lines"),
       "poet": ("runner_poet_c1", "a sumi ink-wash painting"), "ames": ("runner_ames_c1", "a smooth airbrushed gouache painting in one grey-teal hue"),
       "band": ("runner_band_b1", "a two-colour risograph print with coarse halftone dots"), "chezjj": ("runner_chezjj_c1", "16-bit pixel art with crisp square pixels, moving in small pixel-art animation steps"),
       "home": ("runner_home_c1", "a chalk and pastel drawing"), "violet": ("runner_violet_c1", "a scratchboard engraving of white lines cut out of black")}
for _k, (_s, _m) in KIT.items():
    C["runner_" + _k] = (_s, _m, RUN, {}); VIEWS["runner_" + _k] = "side"

WC = "a watercolour and gouache illustration with white ink for the frost"
NIGHT_ = "a flat cel-shaded anime drawing on black paper, with flat colours and no glow"
C.update({
 "root_fork": ("root_fork_a1", WC, "The white frost grows: the stem lengthens across the dark glass and each of its two branches forks again, so that by three seconds there are four feathered branches, growing steadily like crystals forming, never melting or fading. The small warm glow under the child's fingertips pulses gently; the fingertips stay where they are. No face ever enters the picture. The camera is locked off.", {}),
 "root_face": ("root_face_a1", WC, "The little girl watches the frost, quietly amazed: she blinks once, and her eyes slowly follow the frost as it grows. On the glass the white frost crystals keep growing and branching toward the left, and their pale light flickers softly on her face. She stays in profile, almost still. A very slow push-in.", {}),
 "main_palm": ("main_palm_a1", NIGHT_, "She holds her palm pressed flat forward and stays almost still, her back to the viewer the whole time, her hair stirring. From under her palm the tree of thin coloured lines keeps growing away from her, its tips lengthening and forking again and again toward the left edge, glimmering slightly as in hand-drawn animation. The small warm glow under her hand pulses once. The camera is locked off.", {}),
 "float_top": ("float_top_a1", NIGHT_, "She floats on her back, perfectly at rest, eyes closed the whole time. Her long hair drifts slowly outward on the water, the separate strands lengthening toward the edges of the picture; the thin white ripple rings widen slowly. The view from directly above turns very slowly clockwise and pulls back a little. The water stays plain black paper.", {}),
 "float_face": ("float_face_a1", NIGHT_, "She floats at rest with her eyes closed the whole time; her eyes move a little under the closed lids, as in a dream, and she breathes slowly. The thin white ripples lap gently at her cheeks and shoulders and her hair drifts on the water. The camera is locked off.", {}),
 "float_hand": ("float_hand_a1", NIGHT_, "The small point of light travels the last of the way along the rose-pink line and settles into her open palm at about one and a half seconds; her fingers, which keep exactly five fingers, curl gently around it, and a ring of thin white ripples spreads from the hand. The light stays, glowing softly with short drawn rays. Only her hand and forearm are ever in the picture. The camera is locked off.", {}),
 "rise": ("rise_a1", NIGHT_, "She keeps rising slowly out of the water, opening her arms wider and lifting her face, calm and glad, lips closed; water runs off her sleeves and hair in drawn white drops, and the ripples widen around her. Behind her the level band of gold dawn grows a little taller and brighter, drawn with more horizontal strokes of golden pencil; above it the paper stays black. A very slow push-in.", {}),
})
VIEWS.update({"root_fork": "none", "root_face": "none", "main_palm": "back", "float_top": "front", "float_face": "front", "float_hand": "none", "rise": "front"})

SB = "a scratchboard engraving of fine white lines cut out of solid black, with violet as its only colour"
STARS = " The engraved stars twinkle faintly and the fine white lines shimmer slightly as in hand-drawn animation; the picture stays an engraving in every frame."
C.update({
 "vio_wide": ("vio_wide_a1", SB, "The tiny figure walks steadily toward the left along the thin violet line, with a calm even step, getting no larger. The camera is locked off." + STARS, {}),
 "vio_walk": ("vio_walk_a1", SB, "She walks toward the left at an easy, even pace, exactly side-on, arms swinging naturally, looking ahead; the camera tracks with her so she stays in the same place in the frame, and the engraved sky slides slowly past behind her." + STARS, {}),
 "vio_close": ("vio_close_a1", SB, "She looks up at the stars, calm and curious; she blinks once and her eyes move slowly across the sky; a loose strand of hair stirs. She stays in profile. A very slow push-in." + STARS, {}),
 "vio_lookback": ("vio_lookback_fix_a1", SB, "She stands still, looking back over her shoulder toward the small sliver of sunrise far away at the right; she blinks once, a quiet look of recognition, lips closed; her body stays facing away. The sliver of warm sunrise brightens very slightly and stays small. Her arm on the right side of the picture has a plain violet band and never a patch. The camera is locked off." + STARS, {}),
 "vio_climb": ("vio_climb_a1", SB, "She climbs the steel ladder steadily, hand over hand, three or four rungs, her back to the viewer the whole time, toward the rim of the dish. The camera is locked off." + STARS, {}),
 "vio_pencil": ("vio_pencil_b1", SB, "With her raised right hand she slowly draws one yellow pencil out of her bun and holds it up beside her head; the bun stays in place with the other pencil still in it; a few loose strands fall. We stay behind her shoulder and never see her whole face. Her hand keeps exactly five fingers. The camera is locked off." + STARS, {}),
 "vio_write": ("vio_write_a1", SB, "She writes in the air with the pencil: her raised hand moves slowly from left to right in small, even writing movements, as if writing one short line of words on the sky, then pauses. Nothing appears in the sky: no line, no letters, no light; the sky where she writes stays empty and dark. Her back stays to the viewer. The camera is locked off." + STARS, {}),
 "vio_release": ("vio_release_b1", SB, "She slowly opens her lifted hand wider and raises it a little, letting something go into the sky, and her head tilts up to follow it as it rises; then her hand lowers gently toward her lap. Nothing visible leaves her hand: the sky stays empty. The small sliver of sunrise on the horizon stays as it is. The camera is locked off." + STARS, {}),
 "vio_still": ("vio_still_a1", SB, "She sits perfectly still with her hands in her lap, looking out at the Milky Way; only her breathing and one loose strand of hair move. The camera is locked off, with the slowest possible pull-back." + STARS, {}),
 "drop_face": ("drop_face_a1", "a flat cel-shaded anime drawing on black paper in gold and black, with flat colours and no glow", "Her face is lifted to the sun with her eyes closed the whole time; she breathes in slowly and deeply, her shoulders rising, and breathes out; her hair stirs. The gold pencil strokes of the sun disc behind her flicker slightly as in hand-drawn animation; the sun does not glow or bloom. A very slow push-in.", {}),
})
VIEWS.update({"vio_wide": "back", "vio_walk": "side", "vio_close": "side", "vio_lookback": "back", "vio_climb": "back", "vio_pencil": "back", "vio_write": "back", "vio_release": "back", "vio_still": "back", "drop_face": "front"})
SPLIT = ("The video begins on the first frame and ends exactly on the last frame. It is a flat cel-shaded anime drawing on black paper and stays that in every frame; never photographic, never 3D. The camera is locked off. "
         "For the first half second one woman stands alone and still in the centre. Then she steps apart into two: an identical copy of her slides out sideways from her, so that two whole identical women stand side by side; then each of the two steps apart into two again, so that by about three seconds there are four identical women in a row, exactly as in the last frame. "
         "At every moment each one is a whole, complete, solid body with her own face, arms and legs: nobody is ever cut in half, stretched, melted or transparent. As they separate, the copies' arm bands, straps and headphones change colour to rose pink, golden yellow and mint green, and a thin drawn line of her own colour runs out under each one's feet. "
         "They arrive exactly at the last frame and hold it for the final second and a half, nearly still, hair stirring. Calm faces, lips closed." + END)
PATCH = ("The video begins on the first frame and ends exactly on the last frame. It is one hand-made drawing of one woman, who stays in the same pose, the same place and the same size throughout; the camera is locked off. "
         "For the first second the patchwork of art mediums on her shimmers gently as in hand-drawn animation and she blinks once. Then, over about two and a half seconds, the patches settle: starting from her face and spreading outward over her hair, jacket, arms and trousers, "
         "each patch of a different medium smooths into clean flat cel-shaded anime colour with a clean inked line, the torn-paper seams closing and disappearing, while behind her the white paper fills with a bright pale-blue morning sky. "
         "It arrives at exactly the last frame and holds it, nearly still, her hair stirring a little, for the final second. She does not walk or turn; never photographic, never 3D." + END)
def ref(src, out):
    os.makedirs(os.path.dirname(out), exist_ok=True)
    subprocess.run(["ffmpeg", "-v", "error", "-y", "-i", src, "-vf", "scale=2048:1152:flags=lanczos", "-q:v", "2", out], check=True)
def still(n):
    for e in (".jpg", ".png"):
        p = os.path.join(ROOT, "work_fable/take2/stills", n + e)
        if os.path.exists(p): return p
    raise SystemExit("no still " + n)
want = [a for a in sys.argv[1:] if not a.startswith("--")] or list(C)
take = next((a.split("=")[1] for a in sys.argv if a.startswith("--take=")), "1")
os.makedirs(os.path.join(ROOT, "media/gen/specs"), exist_ok=True)
for w in want:
    i, _, alt = w.partition("="); st, medium, action, extra = C[i]; st = alt or st
    ref(still(st), os.path.join(ROOT, f"work_fable/take2/refs/{i}.jpg"))
    prompt = (PATCH if i == "patch_resolve" else SPLIT if i == "main_split" else KEEP.format(m=medium) + action + END).replace("{END}", END0.format(L=LETTER[VIEWS[i]]))
    inp = {"prompt": prompt, "image": f"file:work_fable/take2/refs/{i}.jpg", "duration": 5, "resolution": "720p", "use_virtual_avatar": True, "aspect_ratio": "16:9"}
    if i.startswith("runner"): inp["camera_fixed"] = True
    if extra.get("last"):
        ref(still(extra["last"]), os.path.join(ROOT, f"work_fable/take2/refs/{i}_last.jpg")); inp["last_frame_image"] = f"file:work_fable/take2/refs/{i}_last.jpg"
    spec = {"model": "bytedance/seedance-2.5", "tag": f"t2_{i}_t{take}", "notes": json.dumps({"take2": i, "still": st}), "input": inp}
    out = os.path.join(ROOT, "media/gen/specs", f"t2_{i}_t{take}.json"); json.dump(spec, open(out, "w"), indent=1); print(os.path.relpath(out, ROOT))
